verus! {
    // For two equal‐length vectors a and b of i8, produce a boolean vector
    // where each entry indicates a[i] >= b[i].
    fn greater_equal(a: Vec<i8>, b: Vec<i8>) -> (res: Vec<bool>)
        requires
            a.len() == b.len(),
        ensures
            res.len() == a.len(),
            forall |i: nat| i < a.len() ==> res.index(i) == (a.index(i) >= b.index(i)),
    {
        let mut result: Vec<bool> = Vec::new();
        let mut i: nat = 0;
        while i < a.len()
            invariant
                i <= a.len(),
                result.len() == i,
                forall |j: nat| j < i ==> result.index(j) == (a.index(j) >= b.index(j)),
            decreases
                a.len() - i,
        {
            let ai: i8 = a.index(i);
            let bi: i8 = b.index(i);
            result.push(ai >= bi);
            i = i + 1;
        }
        result
    }
}

